Lesson: VII-M4-L04 - "Imagini și linkuri în HTML" (Grade VII, Romanian curriculum)

Knowledge content:
{
  "levels": [
    {
      "level": "general",
      "concepts": [
        "Imaginile fac paginile mai atractive și informative",
        "Linkurile conecteaza paginile web între ele - de aici vine 'web' (panza de paianjen)"
      ]
    },
    {
      "level": "intermediate",
      "concepts": [
        "Tag-ul <img> inserează imagini și are atribute obligatorii",
        "Tag-ul <a> creează linkuri (anchor = ancora)",
        "Calea (path) poate fi relativa sau absoluta"
      ]
    },
    {
      "level": "specific",
      "concepts": [
        "<img src='cale' alt='descriere'> - src indica sursa, alt descrie imaginea",
        "Atributele width și height controleaza dimensiunea",
        "<a href='url'>text</a> - href indica destinatia, textul e clickabil",
        "Cai relative: 'imagine.jpg', '../folder/imagine.jpg'",
        "Cai absolute: 'https://site.com/imagine.jpg'",
        "target='_blank' deschide linkul în tab nou"
      ]
    }
  ]
}

Instructional content:
{
  "hook": {
    "duration_minutes": 3,
    "activity": "Deschideti o pagină populara (Wikipedia, un site de stiri). Dezactivati imaginile din browser (sau aratati versiunea text-only). Intrebati: 'Ati folosi acest site asa? De ce nu?' Apoi aratati aceeași pagină cu imagini. 'Astazi învățăm să aducem viata în paginile noastre!'",
    "connection_to_prior": "Avem deja pagini cu text structurat. Acum adăugăm elementele care fac web-ul vizual și interactiv."
  },
  "micro_lecture": {
    "duration_minutes": 10,
    "key_terms": [
      {
        "term": "<img> (image)",
        "definition": "Tag pentru inserarea imaginilor. Este un tag fara închidere (self-closing).",
        "analogy": "Ca un cadru foto pe perete - arată o imagine dar nu contine text"
      },
      {
        "term": "src (source)",
        "definition": "Atribut obligatoriu care indica locatia fisierului imagine",
        "analogy": "Ca adresa de pe un plic - spune unde să găsească imaginea"
      },
      {
        "term": "alt (alternative text)",
        "definition": "Text descriptiv afisat dacă imaginea nu se incarca sau pentru screen readers",
        "analogy": "Ca descrierea unei fotografii pentru cineva care nu o poate vedea"
      },
      {
        "term": "<a> (anchor)",
        "definition": "Tag pentru crearea hiperlegaturilor clickabile",
        "analogy": "Ca o usa catre alta camera - click și ajungi în alt loc"
      },
      {
        "term": "href (hypertext reference)",
        "definition": "Atribut care indica URL-ul sau pagină destinatie",
        "analogy": "Ca adresa scrisa pe usa - spune unde duce"
      },
      {
        "term": "Cale relativa vs absoluta",
        "definition": "Relativa: față de fișierul curent ('img/poza.jpg'). Absoluta: adresa completă ('https://...')",
        "analogy": "Relativa: 'du-te la usa din stanga'. Absoluta: 'du-te la Strada X, Nr. Y, Apt. Z'"
      }
    ],
    "explain_like_im_12": "Imaginati-va ca faceti un album foto digital. Tag-ul <img> e ca rama foto - ii spui ce poza să afiseze (src) și ce să scrie dacă poza lipseste (alt). Tag-ul <a> e ca un link magic - scrii un text, și când cineva da click, teleporteaza pe alt site sau pagină. Simplu!",
    "visual_aids": [
      "Diagrama cu sintaxa <img> și atributele sale",
      "Diagrama cu sintaxa <a> și exemplu de link",
      "Comparatie cale relativa vs absoluta cu structura de foldere"
    ]
  },
  "practice_guided": {
    "duration_minutes": 15,
    "tasks": [
      {
        "task": "Pregateste imaginile",
        "steps": [
          "În folderul cu proiectul tau HTML, creează un subfolder 'imagini'",
          "Descarca sau copiază 2-3 imagini mici (max 500KB) în acel folder",
          "Redenumește-le simplu: 'foto1.jpg', 'logo.png' (fara spații, fara diacritice!)"
        ],
        "teacher_support": "Ofera imagini pre-descarcate pe stick sau rețea locala pentru elevii fara internet"
      },
      {
        "task": "Inserează prima imagine",
        "steps": [
          "Deschide pagină ta HTML în editor",
          "În body, adaugă: <img src='imagini/foto1.jpg' alt='Descriere imagine'>",
          "Salvează și deschide în browser",
          "Dacă imaginea nu apare, verifică: calea e corectă? numele fisierului e exact?",
          "Adaugă dimensiuni: <img src='imagini/foto1.jpg' alt='Descriere' width='300'>"
        ],
        "teacher_support": "Cel mai comun error: calea greșită. Verifică structura de foldere cu elevii."
      },
      {
        "task": "Creează primul link",
        "steps": [
          "Adaugă un paragraf cu: <a href='https://www.google.com'>Cauta pe Google</a>",
          "Salvează și testeaza - click pe link",
          "Modifică pentru a deschide în tab nou: <a href='https://www.google.com' target='_blank'>Cauta pe Google</a>",
          "Creează un link intern catre alta pagină din proiect: <a href='despre_mine.html'>Despre mine</a>"
        ],
        "teacher_support": "Explică diferenta link extern (alt site) vs intern (alta pagină din proiect)"
      },
      {
        "task": "Combina: imagine ca link",
        "steps": [
          "Pune tag-ul img ÎN INTERIORUL tag-ului a:",
          "<a href='https://wikipedia.org'><img src='imagini/logo.png' alt='Logo Wikipedia'></a>",
          "Testeaza: acum imaginea e clickabila!"
        ],
        "teacher_support": "Arată cum se imbrica tag-urile: a contine img"
      }
    ],
    "success_criteria": [
      "Cel putin o imagine apare corect pe pagină",
      "Imaginea are atribut alt descriptiv",
      "Există cel putin un link functional extern",
      "Există cel putin un link intern catre alta pagină"
    ]
  },
  "practice_independent": {
    "duration_minutes": 15,
    "levels": {
      "minim": [
        {
          "task": "Creează pagină 'galerie.html' cu: titlu h1, 3 imagini cu alt text descriptiv, un link catre pagină principală și un link extern catre un site preferat.",
          "expected_output": "Pagină cu 3 imagini vizibile și 2 linkuri functionale"
        }
      ],
      "standard": [
        {
          "task": "Creează un mini-site cu 2 pagini: 'index.html' (pagină principală) și 'contact.html'. Fiecare pagină să aiba: imagine relevanta, link catre cealalta pagină (navigare), și 2 linkuri externe. Imaginile să aiba dimensiuni specificate.",
          "expected_output": "Doua pagini interconectate cu imagini și linkuri functionale"
        }
      ],
      "performanta": [
        {
          "task": "Creează o pagină 'resurse.html' cu o lista de resurse educationale. Fiecare resursa să aiba: imagine/logo, titlu ca link (deschide în tab nou), scurta descriere. Adaugă o imagine care lipseste intentionat pentru a demonstra utilitatea atributului alt. Cerceteaza și folosește atributul title pentru linkuri.",
          "expected_output": "Pagină cu lista formatata, imagini ca linkuri, alt functional pentru imagine lipsa, title pe linkuri"
        }
      ]
    }
  },
  "wrap_up": {
    "duration_minutes": 7,
    "exit_ticket": {
      "minim": [
        "Ce atribute sunt obligatorii pentru tag-ul img? De ce e important alt?"
      ],
      "standard": [
        "Scrie codul pentru un link care deschide Google în tab nou. Explică fiecare parte."
      ],
      "performanta": [
        "Care e diferenta dintre o cale relativa și una absoluta pentru imagini? Când folosești fiecare?"
      ]
    },
    "preview_next": "Saptamana viitoare învățăm CSS - cum să facem paginile să arate spectaculos cu culori, fonturi și stiluri!"
  }
}

